            {"type": "function_call", "call_id": "c2", "name": "ls", "arguments": "{\"p\":\"/var\"}"},
            {"type": "function_call_output", "call_id": "c1", "output": "a"},
            {"type": "function_call_output", "call_id": "c2", "output": "b"}
