3876	/// Per-model serving readiness gate.
3877	///
3878	/// Composes AND-wise with [`check_ready`]: a request is admitted only when
3879	/// (a) the process is ready (`check_ready`) AND (b) at least one namespace
3880	/// for this specific model has a complete set of workers — every worker's
3881	/// `needs` DNF is satisfied by the worker types currently present in that
3882	/// namespace.
3883	///
3884	/// Returns `503 Service Unavailable` with a structured body when the model
3885	/// isn't ready to serve. Models absent from the committed catalog, including
3886	/// discovered models still being built, fall through here; the per-handler
3887	/// engine lookup later in the request path returns a 404 instead.
3888	pub(crate) fn check_model_serving_ready(
3889	    state: &Arc<service_v2::State>,
3890	    model_name: &str,
3891	) -> Result<(), ErrorResponse> {
3892	    let Some(model) = state.manager().get_committed_model(model_name) else {
3893	        // Not committed — let the per-endpoint engine accessor produce the
3894	        // canonical 404. The readiness gate has nothing to say.
3895	        return Ok(());
3896	    };
3897	    if model.has_ready_workers() {
3898	        return Ok(());
3899	    }
3900	    Err(ErrorMessage::service_unavailable_with_body(
3901	        model_not_ready_message(model_name),
3902	    ))
3903	}

